const task = items[0]?.json || {};
const desc = (task.description || '').toLowerCase();
const routing = {
  vagary_index: ['travel', 'country', 'guide', 'tiktok', 'currency'],
  shoes: ['shoe', 'inventory', 'ad copy', 'ecommerce'],
  gamedev: ['aura', 'card', 'trinity', 'nfc', 'ue5', 'unreal', 'c++'],
  kids: ['bedtime', 'story', 'tts', 'narration', 'child-safe'],
  innovation: ['patent', 'white paper', 'ip', 'tech'],
  ewaste: ['recycling', 'gold', 'copper', 'palladium'],
  quantum: ['thermal', 'biometric', 'wearable', 'physics']
};
let targetSector = null;
for (const [sector, keywords] of Object.entries(routing)) {
  if (keywords.some(kw => desc.includes(kw))) {
    targetSector = sector;
    break;
  }
}
return [{json: {task_id: task.id, target_sector: targetSector, dispatched: true, title: task.title}}];
